import{_ as e,o as t,c as a,a2 as r}from"./chunks/framework.Buc7gXeZ.js";const g=JSON.parse('{"title":"编目体系：标签 / 货架 / 封面 / 多语言","description":"MetaFusion LRM 编目模型、自由标签体系、虚拟货架规则与多语言本地化体系。","frontmatter":{"title":"编目体系：标签 / 货架 / 封面 / 多语言","description":"MetaFusion LRM 编目模型、自由标签体系、虚拟货架规则与多语言本地化体系。","order":11,"group":"model"},"headers":[],"relativePath":"taxonomy.md","filePath":"taxonomy.md"}'),d={name:"taxonomy.md"};function l(c,o,i,s,n,u){return t(),a("div",null,[...o[0]||(o[0]=[r('<h1 id="编目体系-标签-货架-封面-多语言" tabindex="-1">编目体系：标签 / 货架 / 封面 / 多语言 <a class="header-anchor" href="#编目体系-标签-货架-封面-多语言" aria-label="Permalink to &quot;编目体系：标签 / 货架 / 封面 / 多语言&quot;">​</a></h1><p>MetaFusion 采用 <strong>IFLA LRM 混合编目模型</strong>。固定实体骨架为八类（<code>agent / collection / work / content_unit / expression / release / medium / track</code>），保持纯净标题与核心概念，业务形态由服务端动态 definitions 的 <code>types</code> 表达，规格由 Release / Medium 载体表达，检索特征通过「<strong>自由标签 + 虚拟货架 + 实体图谱边</strong>」自然呈现，彻底淘汰传统的硬编码 <code>media_type</code> 与僵化的单继承分类树。</p><hr><h2 id="_1-自由标签体系-tags" tabindex="-1">1. 自由标签体系 (Tags) <a class="header-anchor" href="#_1-自由标签体系-tags" aria-label="Permalink to &quot;1. 自由标签体系 (Tags)&quot;">​</a></h2><p>标签（<code>attributes.tags</code>）是平铺、自由的字符串列表，专用于流派、题材、风格与大众特色检索词（如 <code>J-Pop</code>、<code>科幻</code>、<code>机甲</code>、<code>治愈</code>、<code>摇滚</code>、<code>同人</code>）：</p><ul><li><strong>平铺无分类</strong>：标签不设立人为的 <code>group_type</code> 或分类树，保持纯粹的自由检索与群众标注属性；</li><li><strong>职责解耦</strong>： <ul><li><strong>业务类型（Types）</strong>：作品宏观业务类型（如 <code>animation</code>、<code>album</code>、<code>single</code>、<code>novel</code> 等）通过 <code>Entity.types</code> 挂载，并自动引用服务端 definitions 的动态字段方案（Inclusion Scheme）与展示模板；</li><li><strong>载体规格（Medium Format）</strong>：物理与分发规格（如 <code>CD</code>、<code>BD</code>、<code>Vinyl</code>、<code>DVD</code>、<code>Paper</code>、<code>Web</code>）归属于发行版（Release）及载体介质（Medium），不作为概念层 Work 的标签；</li><li><strong>自由标签（Tags）</strong>：记录题材、流派与风格，底层通过 GIN 路径索引支持高效包含匹配，由 <code>GET /api/catalog/tags</code> 提供实时频次聚合。</li></ul></li></ul><blockquote><p><strong>注</strong>：发行规格（如 <code>4K UHD</code>、<code>Hi-Res FLAC</code>、<code>SACD</code>、<code>EPUB</code>）属于发行版与物理 Medium 属性，不再作为 Work 标签，避免概念层与实物层混淆。</p></blockquote><hr><h2 id="_2-虚拟货架体系-virtual-shelves" tabindex="-1">2. 虚拟货架体系 (Virtual Shelves) <a class="header-anchor" href="#_2-虚拟货架体系-virtual-shelves" aria-label="Permalink to &quot;2. 虚拟货架体系 (Virtual Shelves)&quot;">​</a></h2><p>虚拟货架将作品分类从“死板的物理目录树”转变为“<strong>活的动态规则筛选器</strong>”。</p><h3 id="_2-1-规则机制" tabindex="-1">2.1 规则机制 <a class="header-anchor" href="#_2-1-规则机制" aria-label="Permalink to &quot;2.1 规则机制&quot;">​</a></h3><p>每个货架由一组标签规则定义：</p><ul><li><code>query_tags</code>：包含的标签集合（如 <code>[&quot;动画&quot;, &quot;电影&quot;]</code> 或 <code>[&quot;Hi-Res&quot;, &quot;爵士&quot;]</code>）</li><li><code>require_all_tags</code>：<code>true</code> 表示必须同时满足全部标签（AND），<code>false</code> 表示满足任一标签（OR）</li><li><code>exclude_tags</code>：排除的标签集合（NOT）</li></ul><h3 id="_2-2-用户自定义货架与频道" tabindex="-1">2.2 用户自定义货架与频道 <a class="header-anchor" href="#_2-2-用户自定义货架与频道" aria-label="Permalink to &quot;2.2 用户自定义货架与频道&quot;">​</a></h3><ul><li>平台预设公共货架（如“剧场动画”、“无损专辑”、“精选小说”）；</li><li>用户可在个人首页自由新建、配置自定义货架，并支持拖拽排版与一键公开分享。</li></ul><hr><h2 id="_3-封面自适应与多比例系统" tabindex="-1">3. 封面自适应与多比例系统 <a class="header-anchor" href="#_3-封面自适应与多比例系统" aria-label="Permalink to &quot;3. 封面自适应与多比例系统&quot;">​</a></h2><p>MetaFusion 尊重各媒介载体的传统排版与艺术设计习惯，支持<strong>自然宽高比自适应</strong>与<strong>精确比例控制</strong>：</p><h3 id="_3-1-比例标准" tabindex="-1">3.1 比例标准 <a class="header-anchor" href="#_3-1-比例标准" aria-label="Permalink to &quot;3.1 比例标准&quot;">​</a></h3><ul><li><strong>方形 1:1</strong>：音乐唱片、EP、原声大碟（OST）、单曲；</li><li><strong>竖向海报 2:3</strong>：电影、电视动画、真人剧集海报；</li><li><strong>标准书页 3:4</strong>：轻小说、单行本漫画、出版物、画集。</li></ul><h3 id="_3-2-判定与覆盖机制" tabindex="-1">3.2 判定与覆盖机制 <a class="header-anchor" href="#_3-2-判定与覆盖机制" aria-label="Permalink to &quot;3.2 判定与覆盖机制&quot;">​</a></h3><ol><li><strong>手动指定</strong>：作品表记录 <code>works.cover_aspect</code>（如 <code>&quot;1:1&quot;</code>、<code>&quot;2:3&quot;</code>、<code>&quot;3:4&quot;</code>）。当用户显式指定时，严格按照指定比例渲染；</li><li><strong>自动推断</strong>：当 <code>cover_aspect</code> 为空时，前端根据作品的 <code>format</code> 标签自动推断典型比例；</li><li><strong>自适应渲染</strong>：组件支持平滑过渡，并在占位符阶段根据比例提前布局，杜绝布局抖动（CLS）。</li></ol><hr><h2 id="_4-多语言本地化体系-translations" tabindex="-1">4. 多语言本地化体系 (Translations) <a class="header-anchor" href="#_4-多语言本地化体系-translations" aria-label="Permalink to &quot;4. 多语言本地化体系 (Translations)&quot;">​</a></h2><p>MetaFusion 具备完整的国际化编目支持，所有主实体均通过 <code>_translations</code> 表保存各语种译名与简介：</p><ul><li><strong>支持语种</strong>：<code>zh-CN</code>（简体中文）、<code>zh-TW</code>（繁体中文）、<code>en-US</code>（英语）、<code>ja</code>（日语）、<code>ko</code>（韩语）等；</li><li><strong>主表与回退链</strong>： <ol><li>主表的 <code>title</code> / <code>summary</code>（或 <code>name</code> / <code>biography</code>）作为默认语种基准；</li><li>访问页面时通过界面顶部的语言切换器选择偏好语言；</li><li>系统优先展示对应语种的精确翻译与本地化简介，未命中时平滑回退到默认语种与原文标题。</li></ol></li></ul><hr><h2 id="_5-探索页与组合筛选指南" tabindex="-1">5. 探索页与组合筛选指南 <a class="header-anchor" href="#_5-探索页与组合筛选指南" aria-label="Permalink to &quot;5. 探索页与组合筛选指南&quot;">​</a></h2><p>在探索页面（<code>/explore</code>），你可以利用动态类型与标签体系快速发现感兴趣的内容：</p><ul><li><strong>货架切换</strong>：在页面顶部可直接切换不同的预设虚拟货架（如“剧场版动画”、“高解析音频专区”）或自己的自定义货架；</li><li><strong>标签组合筛选</strong>：点击标签栏选择一个或多个标签，支持切换「同时满足（全部匹配）」或「满足其一（任一匹配）」模式；</li><li><strong>关键词搜索</strong>：在搜索栏输入原名、中文名、外文别名或创作者名称，系统提供即时联想与全文检索；</li><li><strong>灵活排序</strong>：支持按收录时间、浏览热度、首字母标题、发行日期等维度进行排序；</li><li><strong>开发者调用</strong>：如需通过外部程序自动化检索或批量拉取货架与标签数据，请参阅专门的 <a href="/docs/api-lookup-browse">API 检索与浏览指引</a>。</li></ul>',30)])])}const _=e(d,[["render",l]]);export{g as __pageData,_ as default};
